import { createRouter, createWebHistory } from 'vue-router';
import Home from '@/views/Home.vue';
import Academic from '@/views/Academic.vue';
import Blog from '@/views/blogs/Blog.vue';
import Illusion from '@/views/illusions/Illusions.vue';

const routes = [
  { path: '/', component: Home },        
  { path: '/academic', component: Academic },
  { path: '/blog', name:'Blog', component: Blog },
  {
    path: '/blog/sexuality-study',
    name: 'SexualityStudy',
    component: () => import('@/views/blogs/SexualityStudy.vue')
  },
  {
    path: '/blog/comp690',
    name: 'Comp690',
    component: () => import('@/views/Unavailable.vue')
  },
  {path: '/illusion', name:'Illusion', component: Illusion },
    {
    path: '/illusion/light-flash',
    name: 'LightFlash',
    component: () => import('@/views/illusions/LightFlash.vue')
  },
  {
    path: '/illusion/carolina-blue',
    name: 'CarolinaBlue',
    component: () => import('@/views/illusions/CarolinaBlue.vue')
  },
    {
    path: '/academic/research', 
    name: 'Research',
    redirect: '/academic#research'
  },
    {
    path: '/academic/research/mitacs', 
    name: 'Mitacs',
    component: () => import('@/views/academic/Mitacs.vue')
  },
      {
    path: '/academic/study', 
    name: 'Study',
    component: () => import('@/views/academic/Study.vue'),
    redirect: '/academic#projects',
    children: [
      { path: 'junior-projects', component: () => import('@/views/academic/Junior.vue') },
    ]
  },
];

const labels = {
  '/': 'About', '/academic': 'Research & projects', '/blog': 'Writing', '/illusion': 'Photos',
  '/blog/sexuality-study': 'Sexuality study', '/blog/comp690': 'Page unavailable',
  '/illusion/light-flash': 'Light flash', '/illusion/carolina-blue': 'Carolina Blue',
  '/academic/research/mitacs': 'Metaheuristic optimization',
  '/academic/study/junior-projects': 'Course projects'
};
function addMetadata(records, prefix = '') {
  records.forEach(route => {
    const path = route.path.startsWith('/') ? route.path : `${prefix}/${route.path}`;
    route.meta = { title: labels[path] || 'Page unavailable' };
    const section = ['/academic', '/blog', '/illusion'].find(base => path.startsWith(base + '/'));
    if (section) route.meta.parent = { label: labels[section], to: section };
    if (route.children) addMetadata(route.children, path);
  });
}
addMetadata(routes);
routes.push({ path: '/:pathMatch(.*)*', component: () => import('@/views/Unavailable.vue') });

const router = createRouter({
  history: createWebHistory(),
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) return savedPosition;
    if (to.hash) return { el: to.hash, top: 24 };
    return { top: 0 };
  }
});

router.afterEach((to) => { document.title = to.path === '/' ? 'Zhen Qi | Computer Science' : `${to.meta.title || 'Page unavailable'} | Zhen Qi`; });

export default router;